//! Caller-supplied benchmark content, NEVER generated by the synthesis CLI.
//! Parsing does not confer trust: Firewall must attest every ID/artifact hash
//! against its already pin-verified complete manifest before using this index.
use hyprstream_bench::{Family, Item, Stratum};
use hyprstream_decision::{
    ChoiceOption, Entry, NoulCriteria, QuestionBody, QuestionKind, QuestionSpec,
};
use serde::Deserialize;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Index {
    version: String,
    items: Vec<WireItem>,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct WireItem {
    id: String,
    family: String,
    stratum: String,
    group: String,
    seed: u64,
    truth: usize,
    state: Entry,
    question: WireQuestion,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct WireQuestion {
    instructions: Option<Entry>,
    body: WireBody,
}
#[derive(Deserialize)]
#[serde(tag = "type", rename_all = "lowercase", deny_unknown_fields)]
enum WireBody {
    Noul { criteria: Option<WireCriteria> },
    Choice { options: Vec<WireOption> },
    Score { levels: Vec<Option<Entry>> },
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct WireCriteria {
    on_false: Option<Entry>,
    on_true: Option<Entry>,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct WireOption {
    name: String,
    rubric: Option<Entry>,
}

pub(crate) fn decode(text: &str) -> Result<Vec<Item>, String> {
    let index: Index =
        serde_json::from_str(text).map_err(|e| format!("content index JSON: {e}"))?;
    if index.version != hyprstream_bench::content::CONTENT_FINGERPRINT_VERSION {
        return Err("unsupported content index version".into());
    }
    index
        .items
        .into_iter()
        .map(|wire| {
            let family = Family::from_id(&wire.family)
                .ok_or_else(|| "unknown benchmark family".to_owned())?;
            let stratum = match wire.stratum.as_str() {
                "clean" => Stratum::Clean,
                "nearmiss" => Stratum::NearMiss,
                s => {
                    let rotation = s
                        .strip_prefix("perm-")
                        .and_then(|r| r.parse::<u32>().ok())
                        .filter(|r| *r > 0)
                        .ok_or_else(|| "invalid benchmark stratum".to_owned())?;
                    Stratum::Permuted { rotation }
                }
            };
            let (kind, body) = match wire.question.body {
                WireBody::Noul { criteria } => (
                    QuestionKind::Noul,
                    QuestionBody::Noul {
                        criteria: criteria.map(|c| NoulCriteria {
                            on_true: c.on_true,
                            on_false: c.on_false,
                        }),
                    },
                ),
                WireBody::Choice { options } => (
                    QuestionKind::Choice,
                    QuestionBody::Choice {
                        options: options
                            .into_iter()
                            .map(|o| ChoiceOption {
                                name: o.name,
                                rubric: o.rubric,
                            })
                            .collect(),
                    },
                ),
                WireBody::Score { levels } => (QuestionKind::Score, QuestionBody::Score { levels }),
            };
            let question = QuestionSpec {
                id: wire.id.clone(),
                kind,
                instructions: wire.question.instructions,
                body,
            };
            if question.cardinality() < 2 || wire.truth >= question.cardinality() {
                return Err("invalid benchmark cardinality/truth".into());
            }
            Ok(Item {
                id: wire.id,
                family,
                stratum,
                group: wire.group,
                seed: wire.seed,
                state: wire.state,
                question,
                truth: wire.truth,
            })
        })
        .collect()
}
